#include <bits/stdc++.h>
using namespace std;
#define int long long

void solve(){
 int n,x,y;cin>>n>>x>>y;
 vector<int> v(n);
 for(int &a:v)cin>>a;
 vector<int> l,r;
 for(int i=0;i<x;i++)l.push_back(v[i]);
 for(int i=y;i<n;i++)l.push_back(v[i]);
 int idx=x,mn=INT_MAX;
 for(int i=x;i<y;i++) if(v[i]<mn) mn=v[i],idx=i;
 for(int i=idx;i<y;i++)r.push_back(v[i]);
 for(int i=x;i<idx;i++)r.push_back(v[i]);
 int pos=l.size();
 for(int i=0;i<l.size();i++) if(!r.empty() && l[i]>r[0]){pos=i;break;}
 for(int i=0;i<pos;i++)cout<<l[i]<<" ";
 for(int x:r)cout<<x<<" ";
 for(int i=pos;i<l.size();i++)cout<<l[i]<<" ";
 cout<<"\n";
}

int32_t main(){ios::sync_with_stdio(false);cin.tie(0);int t;cin>>t;while(t--)solve();}

